CREATE TABLE `brand_versions` (`id` text PRIMARY KEY,`version` text NOT NULL,`category_statement` text NOT NULL,`status` text NOT NULL,`owner` text NOT NULL,`approved_by` text,`approved_at` text);
CREATE TABLE `marketing_audiences` (`id` text PRIMARY KEY,`name` text NOT NULL,`problems_json` text NOT NULL DEFAULT '[]',`outcomes_json` text NOT NULL DEFAULT '[]',`triggers_json` text NOT NULL DEFAULT '[]',`objections_json` text NOT NULL DEFAULT '[]',`evidence_needs_json` text NOT NULL DEFAULT '[]',`channels_json` text NOT NULL DEFAULT '[]',`products_json` text NOT NULL DEFAULT '[]');
CREATE TABLE `messaging_pillars` (`id` text PRIMARY KEY,`brand_version_id` text NOT NULL,`name` text NOT NULL,`message` text NOT NULL,`status` text NOT NULL);
CREATE TABLE `approved_claims` (`id` text PRIMARY KEY,`brand_version_id` text NOT NULL,`claim` text NOT NULL,`scope` text NOT NULL,`status` text NOT NULL,`owner` text NOT NULL,`reviewer` text NOT NULL,`approved_by` text,`expires_at` text);
CREATE TABLE `claim_evidence` (`id` text PRIMARY KEY,`claim_id` text NOT NULL,`source_id` text NOT NULL,`classification` text NOT NULL,`summary` text NOT NULL,`content_hash` text NOT NULL,`verified_at` text NOT NULL);
CREATE TABLE `prohibited_claims` (`id` text PRIMARY KEY,`pattern` text NOT NULL,`reason` text NOT NULL,`status` text NOT NULL);
CREATE TABLE `marketing_permissions` (`id` text PRIMARY KEY,`subject_type` text NOT NULL,`subject_id` text NOT NULL,`permission_type` text NOT NULL,`status` text NOT NULL,`scope` text NOT NULL,`owner` text NOT NULL,`evidence_uri` text,`expires_at` text,`withdrawn_at` text);
CREATE TABLE `channels` (`id` text PRIMARY KEY,`name` text NOT NULL,`adapter_status` text NOT NULL DEFAULT 'Not connected',`owner` text NOT NULL);
CREATE TABLE `campaigns` (`id` text PRIMARY KEY,`objective` text NOT NULL,`audience_id` text NOT NULL,`offer` text NOT NULL,`channels_json` text NOT NULL DEFAULT '[]',`budget_recommendation` real,`status` text NOT NULL,`owner` text NOT NULL,`attribution_method` text NOT NULL,`lead_routing_plan` text NOT NULL,`metrics_json` text NOT NULL DEFAULT '[]',`stop_criteria` text NOT NULL,`risks_json` text NOT NULL DEFAULT '[]',`shared_goal_id` text,`correlation_id` text NOT NULL);
CREATE TABLE `content_assets` (`id` text PRIMARY KEY,`title` text NOT NULL,`objective` text NOT NULL,`audience_id` text NOT NULL,`journey_stage` text NOT NULL,`channel_id` text NOT NULL,`message` text NOT NULL,`cta` text NOT NULL,`owner` text NOT NULL,`reviewer` text NOT NULL,`approver` text NOT NULL,`status` text NOT NULL,`current_version` text NOT NULL,`publication_window_start` text,`publication_window_end` text,`campaign_id` text,`product_id` text,`shared_goal_id` text,`correlation_id` text NOT NULL,`brand_version_id` text NOT NULL,`classification` text NOT NULL);
CREATE TABLE `content_versions` (`id` text PRIMARY KEY,`content_asset_id` text NOT NULL,`version` text NOT NULL,`body` text NOT NULL,`source_ids_json` text NOT NULL DEFAULT '[]',`claim_ids_json` text NOT NULL DEFAULT '[]',`content_hash` text NOT NULL,`created_by` text NOT NULL);
CREATE TABLE `content_approvals` (`id` text PRIMARY KEY,`content_version_id` text NOT NULL,`decision` text NOT NULL,`approver` text NOT NULL,`authority` text NOT NULL,`conditions` text,`decided_at` text NOT NULL);
CREATE TABLE `editorial_calendar` (`id` text PRIMARY KEY,`content_asset_id` text NOT NULL,`window_start` text NOT NULL,`window_end` text NOT NULL,`status` text NOT NULL,`owner` text NOT NULL);
CREATE TABLE `case_studies` (`id` text PRIMARY KEY,`content_asset_id` text NOT NULL,`client_id` text,`anonymized` integer NOT NULL DEFAULT 1,`scope_verified` integer NOT NULL DEFAULT 0,`outcomes_verified` integer NOT NULL DEFAULT 0,`review_owner` text NOT NULL,`withdrawal_requirements` text);
CREATE TABLE `testimonials` (`id` text PRIMARY KEY,`client_id` text NOT NULL,`quote` text NOT NULL,`permission_id` text NOT NULL,`status` text NOT NULL);
CREATE TABLE `campaign_metrics` (`id` text PRIMARY KEY,`campaign_id` text NOT NULL,`metric_name` text NOT NULL,`value` real NOT NULL,`source` text NOT NULL,`window_start` text NOT NULL,`window_end` text NOT NULL);
CREATE TABLE `attribution_events` (`id` text PRIMARY KEY,`campaign_id` text,`content_asset_id` text,`event_type` text NOT NULL,`organization` text,`consent_status` text,`lawful_purpose` text,`retention_rule` text,`deletion_path` text,`occurred_at` text NOT NULL,`correlation_id` text NOT NULL);
CREATE TABLE `content_risks` (`id` text PRIMARY KEY,`content_asset_id` text NOT NULL,`risk_type` text NOT NULL,`severity` text NOT NULL,`description` text NOT NULL,`status` text NOT NULL,`owner` text NOT NULL);
CREATE TABLE `content_audit_events` (`id` text PRIMARY KEY,`content_asset_id` text,`campaign_id` text,`event_type` text NOT NULL,`actor` text NOT NULL,`previous_state` text,`new_state` text,`evidence` text NOT NULL,`authority` text NOT NULL,`occurred_at` text NOT NULL,`correlation_id` text NOT NULL);
CREATE INDEX `content_assets_status_window_idx` ON `content_assets` (`status`,`publication_window_start`);
CREATE INDEX `claims_status_expiry_idx` ON `approved_claims` (`status`,`expires_at`);
CREATE INDEX `permissions_subject_idx` ON `marketing_permissions` (`subject_type`,`subject_id`,`status`);
